	@Test
	void selectedGraphUsesFreshPrivateBindingsWithoutSerializingTheBlankNode() {
		ExclusiveStatement expression = statement("__fedx_graph_0");
		QueryBindingSet input = new QueryBindingSet();
		input.addBinding("__fedx_graph_1", VF.createLiteral("outer"));
		NativeGraphQuery.Prepared prepared = NativeGraphQuery.select(expression, input);
		assertThat(prepared.queryString()).contains("GRAPH ?__fedx_graph_2")
				.doesNotContain(QueryStringUtil.BNODE_URI.stringValue(), "_:selectedGraph");
		assertThat(prepared.graphBindings().getValue("__fedx_graph_2")).isEqualTo(GRAPH);
		try (var rows = source(data).getStatements(prepared, queryInfo)) {
			assertThat(QueryResults.asList(rows)).hasSize(2).allSatisfy(row -> {
				assertThat(row.getBindingNames()).containsExactlyInAnyOrder("__fedx_graph_0", "o", "__fedx_graph_1");
			});
		}
	}

